[CmdletBinding()]param([string]$EnvPath=(Join-Path $PSScriptRoot '.env'))
$ErrorActionPreference='Stop';if(Test-Path $EnvPath){foreach($raw in Get-Content $EnvPath){if($raw-match'^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$'-and-not$raw.TrimStart().StartsWith('#')){$value=$Matches[2].Trim().Trim('"').Trim("'");[Environment]::SetEnvironmentVariable($Matches[1],$value)}}};if(-not$env:NETLD_BASE_URL-or-not$env:NETLD_API_KEY){throw'Set NETLD_BASE_URL and NETLD_API_KEY in the environment file.'};function Resolve-Output($value,$default){if(-not$value){$value=$default};if([IO.Path]::IsPathRooted($value)){$value}else{Join-Path $PSScriptRoot $value}};$strip=($env:NETLD_STRIP_XML ?? 'true').ToLowerInvariant();if($strip-notin@('true','false','1','0','yes','no','on','off')){throw'NETLD_STRIP_XML must be true or false.'};$config=[pscustomobject]@{BaseUrl=$env:NETLD_BASE_URL.TrimEnd('/');ApiKey=$env:NETLD_API_KEY;InitialLookback=$env:NETLD_INITIAL_LOOKBACK ?? '30d';Networks=@((($env:NETLD_NETWORKS ?? '')).Split(',')|ForEach-Object{$_.Trim()}|Where-Object{$_}|Sort-Object -Unique);Target=$env:NETLD_TARGET ?? '';StripXml=$strip-in@('true','1','yes','on');OutputDir=Resolve-Output $env:NETLD_OUTPUT_DIR 'terminal-logs';StatePath=Resolve-Output $env:NETLD_STATE_FILE 'terminal-log-export-state.json';ReportPath=Resolve-Output $env:NETLD_RUN_REPORT_FILE 'terminal-log-export-run.json'};Import-Module (Join-Path $PSScriptRoot 'ExportTerminalLogs.psm1') -Force;try{$report=Invoke-ExportTerminalLogs $config;Write-Host "Found $($report.resultCount) terminal logs and archived $($report.archivedCount) to $($config.OutputDir)";Write-Host "Recorded $($report.failureCount) failures in $($config.ReportPath)";if($report.failureCount){exit 2}}catch{Write-Error $_;exit 1}
